//! Hot reload / hot restart (debug builds).
//!
//! The app library the native shell loads at startup acts as a *trampoline*: when `rux run`
//! sends a newer build, the trampoline `dlopen`s it, tears down the running app, and from then
//! on forwards every start / event / stop to the newest build through a small C ABI that every
//! build exports (generated by `rux::main!`):
//!
//! - `rux_dev_start(host, prev, prev_len, msg, msg_cap) -> u32` — start the app on the given
//!   platform host (backend-specific handle), adopting the previous build's signals;
//! - `rux_dev_dispatch(id, event, value)` — a native event;
//! - `rux_dev_stop(&mut len) -> *const HotSignal` — tear down, returning the app's signals.
//!
//! Builds are never unloaded: adopted signals, closures and `&'static str`s may point into them.

use std::cell::Cell;
use std::ffi::{CStr, CString, c_char, c_void};

use rux_core::App;
use rux_state::hot::{self, HotSignal};

use crate::host;

type StartFn = unsafe extern "C" fn(
    host: *const c_void,
    prev: *const HotSignal,
    prev_len: usize,
    msg: *mut c_char,
    msg_cap: usize,
) -> u32;
type DispatchFn = unsafe extern "C" fn(id: u64, event: *const c_char, value: *const c_char);
type StopFn = unsafe extern "C" fn(len: *mut usize) -> *const HotSignal;

/// Status codes returned by `rux_dev_start`.
const FRESH: u32 = 0;
const KEPT: u32 = 1;
const RESET: u32 = 2;
const FAILED: u32 = 3;

/// How an app build started.
#[derive(Debug, PartialEq, Eq)]
pub enum Started {
    /// Constructed from scratch, nothing to carry over.
    Fresh,
    /// The previous build's state values (count) were adopted.
    Kept(usize),
    /// The previous state didn't fit the new build (reason); constructed from scratch.
    Reset(String),
}

/// Constructs the app, recording its signals (for the next hot reload) and adopting
/// `previous` ones when they all match; otherwise constructs it again from scratch.
pub fn create_app(
    create: fn() -> Box<dyn App>,
    previous: Vec<HotSignal>,
) -> (Box<dyn App>, Started) {
    let count = previous.len();
    hot::begin(previous);
    let app = create();
    match hot::end() {
        None if count == 0 => (app, Started::Fresh),
        None => (app, Started::Kept(count)),
        Some(reason) => {
            drop(app);
            hot::begin(Vec::new());
            let app = create();
            hot::end();
            (app, Started::Reset(reason))
        }
    }
}

// --- trampoline side ----------------------------------------------------------

/// A newer build of the app library, loaded into the process.
pub struct HotLib {
    start: StartFn,
    dispatch: DispatchFn,
    stop: StopFn,
}

thread_local! {
    /// The build currently running the app, once a hot reload happened.
    static ACTIVE: Cell<Option<&'static HotLib>> = const { Cell::new(None) };
}

/// The hot-reloaded build to forward to, if any.
pub fn active() -> Option<&'static HotLib> {
    ACTIVE.with(Cell::get)
}

impl HotLib {
    /// Starts the app in this build on `host` (backend-specific handle).
    ///
    /// # Safety
    /// `host` must be valid for the backend (see `rux_android` / `rux_ios` `dev_start`).
    pub unsafe fn start(
        &self,
        host: *const c_void,
        previous: Vec<HotSignal>,
    ) -> Result<Started, String> {
        let mut msg = [0 as c_char; 512];
        // SAFETY: `previous` and `msg` outlive the call; `host` is the backend's contract.
        let code = unsafe {
            (self.start)(
                host,
                previous.as_ptr(),
                previous.len(),
                msg.as_mut_ptr(),
                msg.len(),
            )
        };
        // SAFETY: the callee NUL-terminates within `msg_cap`.
        let msg = unsafe { CStr::from_ptr(msg.as_ptr()) }
            .to_string_lossy()
            .into_owned();
        match code {
            FRESH => Ok(Started::Fresh),
            KEPT => Ok(Started::Kept(msg.parse().unwrap_or(0))),
            RESET => Ok(Started::Reset(msg)),
            _ => Err(msg),
        }
    }

    pub fn dispatch(&self, id: u64, event: &str, value: Option<&str>) {
        let event = c_string(event);
        let value = value.map(c_string);
        let value_ptr = value.as_ref().map_or(std::ptr::null(), |v| v.as_ptr());
        // SAFETY: the strings outlive the call.
        unsafe { (self.dispatch)(id, event.as_ptr(), value_ptr) }
    }

    /// Stops the app in this build, returning its signals.
    pub fn stop(&self) -> Vec<HotSignal> {
        let mut len = 0;
        // SAFETY: returns `len` entries (leaked by the callee).
        unsafe {
            let ptr = (self.stop)(&mut len);
            if ptr.is_null() {
                Vec::new()
            } else {
                std::slice::from_raw_parts(ptr, len).to_vec()
            }
        }
    }
}

/// Hands the app over to the build at `path`: hot reload (`keep_state`, adopting the running
/// app's state) or hot restart. `stop_local` tears down the trampoline's own runtime (first
/// reload only). Returns a one-line report, `ok …` or `err …`, for `rux run`.
///
/// # Safety
/// `host` must be valid for the backend (see [`HotLib::start`]).
pub unsafe fn reload(
    path: &str,
    keep_state: bool,
    host: *const c_void,
    stop_local: impl FnOnce(),
) -> String {
    // Load first: if this fails, the running app is left untouched.
    let lib = match load(path) {
        Ok(lib) => lib,
        Err(e) => return format!("err loading {path}: {e}"),
    };
    let previous = match active() {
        Some(old) => old.stop(),
        None => {
            stop_local();
            hot::take_current()
        }
    };
    // On hot restart the old signals are dropped with the old build (leaked: dev only).
    let previous = if keep_state { previous } else { Vec::new() };
    ACTIVE.with(|a| a.set(Some(lib)));
    match unsafe { lib.start(host, previous) } {
        Ok(Started::Fresh) if keep_state => "ok hot reload (no state)".into(),
        Ok(Started::Fresh) => "ok hot restart".into(),
        Ok(Started::Kept(n)) => format!("ok hot reload: kept {n} state value(s)"),
        Ok(Started::Reset(reason)) => format!("ok hot restart (state reset: {reason})"),
        Err(e) => format!("err {e}"),
    }
}

fn load(path: &str) -> Result<&'static HotLib, String> {
    // SAFETY: loading our own app library build; its initializers are plain Rust statics.
    let lib = unsafe { libloading::Library::new(path) }.map_err(|e| e.to_string())?;
    let lib: &'static libloading::Library = Box::leak(Box::new(lib)); // never unloaded
    // SAFETY: the symbols are generated by `rux::main!` with these exact signatures.
    unsafe {
        let start = *lib
            .get::<StartFn>(b"rux_dev_start\0")
            .map_err(|e| e.to_string())?;
        let dispatch = *lib
            .get::<DispatchFn>(b"rux_dev_dispatch\0")
            .map_err(|e| e.to_string())?;
        let stop = *lib
            .get::<StopFn>(b"rux_dev_stop\0")
            .map_err(|e| e.to_string())?;
        Ok(Box::leak(Box::new(HotLib {
            start,
            dispatch,
            stop,
        })))
    }
}

fn c_string(s: &str) -> CString {
    CString::new(s.replace('\0', "\u{FFFD}")).expect("no interior NUL")
}

// --- hot build side (helpers for the exported functions) ---------------------

/// Implements `rux_dev_start`: runs `start` (which installs the app and reports how it
/// started), catching panics, and encodes the outcome.
///
/// # Safety
/// `prev` must point to `prev_len` entries (or be null); `msg` to `msg_cap` writable bytes.
pub unsafe fn export_start(
    prev: *const HotSignal,
    prev_len: usize,
    msg: *mut c_char,
    msg_cap: usize,
    start: impl FnOnce(Vec<HotSignal>) -> Started,
) -> u32 {
    let previous = if prev.is_null() {
        Vec::new()
    } else {
        unsafe { std::slice::from_raw_parts(prev, prev_len) }.to_vec()
    };
    let (code, text) = match host::guard("rux_dev_start", || start(previous)) {
        Some(Started::Fresh) => (FRESH, String::new()),
        Some(Started::Kept(n)) => (KEPT, n.to_string()),
        Some(Started::Reset(reason)) => (RESET, reason),
        None => (FAILED, "the app panicked while starting".into()),
    };
    unsafe { write_c(msg, msg_cap, &text) };
    code
}

/// Implements `rux_dev_stop`: runs `stop` (tearing the app down) and returns the app's
/// signals as a leaked array.
///
/// # Safety
/// `len` must be valid for writes.
pub unsafe fn export_stop(len: *mut usize, stop: impl FnOnce()) -> *const HotSignal {
    host::guard("rux_dev_stop", stop);
    let signals = hot::take_current().into_boxed_slice();
    unsafe { *len = signals.len() };
    Box::leak(signals).as_ptr()
}

/// Copies `text` into `buf` as a NUL-terminated string, truncated to fit.
unsafe fn write_c(buf: *mut c_char, cap: usize, text: &str) {
    if buf.is_null() || cap == 0 {
        return;
    }
    let n = text.len().min(cap - 1);
    unsafe {
        std::ptr::copy_nonoverlapping(text.as_ptr().cast::<c_char>(), buf, n);
        *buf.add(n) = 0;
    }
}

#[cfg(test)]
mod tests {
    use rux_core::{App, Element, ElementKind};
    use rux_state::Signal;

    use super::{Started, create_app};

    #[allow(dead_code)] // only constructed: the signals are what's tested
    struct One(Signal<i32>);
    impl App for One {
        fn view(&self) -> Element {
            Element::new(ElementKind::Text)
        }
    }
    #[allow(dead_code)]
    struct Two(Signal<i32>, Signal<bool>);
    impl App for Two {
        fn view(&self) -> Element {
            Element::new(ElementKind::Text)
        }
    }

    #[test]
    fn keeps_matching_state_and_resets_otherwise() {
        let (_app, started) = create_app(|| Box::new(One(Signal::new(1))), Vec::new());
        assert_eq!(started, Started::Fresh);
        let prev = rux_state::hot::take_current();

        let (_app, started) = create_app(|| Box::new(One(Signal::new(0))), prev.clone());
        assert_eq!(started, Started::Kept(1));

        let (_app, started) =
            create_app(|| Box::new(Two(Signal::new(0), Signal::new(false))), prev);
        assert!(matches!(started, Started::Reset(r) if r.contains("new state added")));
        // The fresh rebuild is what gets recorded for the next reload.
        assert_eq!(rux_state::hot::take_current().len(), 2);
    }
}
